targets.rawSql:
SELECT s.latest_telemetry AS "time", s.health_code AS "$layout_machine_id"
FROM public.mis_machine_status s
WHERE s.machine_id = ${layout_machine_id:sqlstring};

WITH selected_machines AS (
  SELECT machine_id FROM (
    SELECT DISTINCT d.eqp_id AS machine_id FROM public.ldi_data d WHERE d.factory IN (${factory:sqlstring}) AND d.process IN (${process:sqlstring}) AND d.eqp_id IN (${machine_id:sqlstring})
    UNION
    SELECT DISTINCT a.equipmentid AS machine_id FROM public.ldi_alarm_log a WHERE a.factory IN (${factory:sqlstring}) AND a.process IN (${process:sqlstring}) AND a.equipmentid IN (${machine_id:sqlstring})
  ) s
), reference AS (SELECT MAX("time") AS reference_time FROM public.ldi_data), latest AS (
  SELECT sm.machine_id, t."time", t.state FROM selected_machines sm
  LEFT JOIN LATERAL (SELECT d."time", d.state FROM public.ldi_data d WHERE d.eqp_id = sm.machine_id ORDER BY d."time" DESC LIMIT 1) t ON TRUE
)
SELECT COUNT(*) FILTER (WHERE l."time" >= r.reference_time - INTERVAL '15 minutes' AND l.state IS TRUE)::double precision AS value FROM latest l CROSS JOIN reference r;

